import {calculate,brackets,validate,round} from './model.js';
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(n), num=n=>new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
let state={version:1,year:2026,income:3000,base:null,tax:20,expenses:[]},current,toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000);}
try{const saved=localStorage.getItem('calcly-state');if(saved)state=validate(JSON.parse(saved));}catch{toast('No se pudo recuperar el estado local. Puedes importar un JSON.');}
function text(id,value){$('#'+id).textContent=value;}
function render(){current=calculate(state);state.base=current.base;const c=current;const values={'returns':money(c.returns),'bracket-name':'tramo '+c.bracket[4],'base-value':money(c.base),'base-min':money(c.bracket[1]),'base-max':money(c.bracket[2]),'factor-base':money(c.base),'fee':money(c.fee),'expense-fee':money(c.fee),'tax-income':money(state.income),'deductions':money(round(c.expenses+c.fee)),'profit':money(c.profit),'tax-factor':`${num(Math.max(0,c.profit))} € × ${state.tax}%`,'tax-total':money(c.tax),'summary-net':money(c.net),'summary-fee':money(c.fee),'summary-tax':money(c.tax),'summary-expenses':money(c.expenses)};Object.entries(values).forEach(([k,v])=>text(k,v));$('#net').replaceChildren(document.createTextNode(num(c.net)+' '));const currency=document.createElement('span');currency.className='currency';currency.textContent='€';$('#net').append(currency);text('result-sentence',`Facturas ${money(state.income)}, pero realmente solo puedes usar ${money(c.net)} al mes, según esta estimación.${c.net<0?' Tus gastos y cuota superan tus ingresos.':''}`);const slider=$('#base');slider.min=c.bracket[1];slider.max=c.bracket[2];slider.value=c.base;slider.style.setProperty('--fill',`${(c.base-c.bracket[1])/(c.bracket[2]-c.bracket[1])*100}%`);$('#brackets').replaceChildren();brackets.forEach((b,i)=>{const row=document.createElement('tr');if(i===c.index){row.className='active-tramo';row.setAttribute('aria-label','Tu tramo: '+b[4]);} [b[3],num(b[1]),num(b[2])].forEach(value=>{const td=document.createElement('td');td.textContent=value;row.append(td);});$('#brackets').append(row);});$('#expenses').replaceChildren();state.expenses.forEach((expense,i)=>{const row=document.createElement('div');row.className='expense-row';const name=document.createElement('span');name.textContent=expense.name;const amount=document.createElement('strong');amount.textContent=money(expense.amount);const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Eliminar '+expense.name);remove.onclick=()=>{state.expenses.splice(i,1);state.base=null;render();};row.append(name,amount,remove);$('#expenses').append(row);});$('#allocation').replaceChildren();const amounts=[Math.max(c.net,0),c.fee,c.tax,c.expenses],total=amounts.reduce((a,b)=>a+b,0);amounts.forEach((value,i)=>{const segment=document.createElement('span');segment.className=['green','purple','orange','gray'][i];segment.style.width=(total?value/total*100:0)+'%';$('#allocation').append(segment);});try{localStorage.setItem('calcly-state',JSON.stringify(state));}catch{toast('El navegador no permite guardar aquí. Exporta tu escenario en JSON.');}}
function sync(){ $('#income').value=state.income;$('#tax').value=state.tax;render();}
$('#income').addEventListener('input',e=>{if(!e.target.validity.valid||e.target.value==='')return;state.income=round(Number(e.target.value));state.base=null;render();});$('#tax').addEventListener('input',e=>{if(!e.target.validity.valid||e.target.value==='')return;state.tax=Number(e.target.value);render();});['income','tax'].forEach(id=>$('#'+id).addEventListener('blur',()=>$('#'+id).value=state[id]));$('#base').addEventListener('input',e=>{state.base=Number(e.target.value);render();});
$('#average').onclick=()=>$('#average-modal').showModal();$('#add-expense').onclick=()=>{if(state.expenses.length>=200){toast('Puedes incluir hasta 200 gastos.');return;}$('#expense-modal').showModal();};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#average-form').onsubmit=e=>{e.preventDefault();const min=Number($('#minimum').value),max=Number($('#maximum').value);if(min>max){text('average-error','El máximo debe ser igual o mayor que el mínimo.');return;}text('average-error','');state.income=round((min+max)/2);state.base=null;sync();$('#average-modal').close();toast('Promedio aplicado a tu facturación.');};
$('#expense-form').onsubmit=e=>{e.preventDefault();const name=$('#expense-name').value.trim();if(!name){$('#expense-name').setCustomValidity('Escribe un nombre para el gasto.');$('#expense-name').reportValidity();return;}state.expenses.push({name,amount:round(Number($('#expense-value').value))});state.base=null;render();$('#expense-modal').close();e.target.reset();};$('#expense-name').oninput=e=>e.target.setCustomValidity('');
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('#export').onclick=()=>{download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'calcly-2026.json');toast('Escenario exportado. Guárdalo para recuperarlo después.');};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('El archivo supera el límite de 1 MB.');const imported=validate(JSON.parse(await file.text()));state=imported;sync();toast('Escenario importado correctamente.');}catch(error){toast(error instanceof SyntaxError?'El archivo no contiene JSON válido.':error.message);}finally{e.target.value='';}};
// A small, dependency-free PDF writer. Everything is generated in this browser.
function makePDF(lines){const escape=s=>Array.from(s).map(ch=>{const code=ch==='€'?128:ch==='−'?45:ch==='×'?215:ch.charCodeAt(0);return code<=255?String.fromCharCode(code):'?';}).join('').replace(/([\\()])/g,'\\$1');const pages=[];for(let i=0;i<lines.length;i+=43)pages.push(lines.slice(i,i+43));const objects=['','<< /Type /Catalog /Pages 2 0 R >>','', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>'];const kids=[];pages.forEach((page,index)=>{const id=objects.length; kids.push(`${id} 0 R`);const content='0.13 0.22 0.17 rg\nBT /F1 12 Tf 48 795 Td 16 TL\n'+page.map(line=>`(${escape(line)}) Tj T*`).join('\n')+`\n(Calcly - ${index+1}/${pages.length}) Tj\nET`;objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${id+1} 0 R >>`);objects.push(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);});objects[2]=`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${pages.length} >>`;let pdf='%PDF-1.4\n',offsets=[0];for(let i=1;i<objects.length;i++){offsets[i]=pdf.length;pdf+=`${i} 0 obj\n${objects[i]}\nendobj\n`;}const offset=pdf.length;pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;offsets.slice(1).forEach(n=>pdf+=String(n).padStart(10,'0')+' 00000 n \n');pdf+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${offset}\n%%EOF`;return new Blob([Uint8Array.from(pdf,ch=>ch.charCodeAt(0))],{type:'application/pdf'});}
$('#pdf').onclick=()=>{const c=current;const lines=['CALCLY | Tus numeros, claros.','Resumen mensual - Ejercicio 2026','Generado: '+new Date().toLocaleDateString('es-ES'),'','DISPONIBLE AL MES: '+money(c.net),'Facturas '+money(state.income)+', disponible estimado '+money(c.net)+'.','','01 / INGRESOS Y TRAMO','Facturacion sin IVA: '+money(state.income),'Otros gastos deducibles: '+money(c.expenses),'Rendimiento para tramo: (ingresos - otros gastos) x 93% = '+money(c.returns),'Tramo '+c.bracket[4]+' | '+c.bracket[3]+' EUR/mes','','02 / CUOTA DE AUTONOMO','Base minima: '+money(c.bracket[1])+' | Base maxima: '+money(c.bracket[2]),'Base elegida: '+money(c.base),'Tipo: 28,30% + 1,30% + 0,90% + 0,10% + 0,90% = 31,50%','Cuota: '+money(c.base)+' x 31,50% = '+money(c.fee),'','03 / GASTOS E IRPF','Cuota (gasto automatico): '+money(c.fee)];state.expenses.forEach(e=>{const label=e.name;for(let i=0;i<label.length;i+=55)lines.push(label.slice(i,i+55)+(i+55>=label.length?' : '+money(e.amount):''));});lines.push('Total gastos con cuota: '+money(round(c.expenses+c.fee)),'Beneficio antes de IRPF: '+money(c.profit),'Reserva: '+money(Math.max(0,c.profit))+' x '+state.tax+'% = '+money(c.tax),'Disponible = facturacion - gastos - cuota - reserva: '+money(c.net),'','ALCANCE DE LA ESTIMACION','Autonomo individual, actividad todo el ano, sin bonificaciones.','La deduccion generica del 7% determina el tramo; no es un gasto real.','Reserva IRPF orientativa: no es la renta anual ni el modelo 130 completo.','No incluye IVA, retenciones ya practicadas ni ajustes personales.','Fuentes: Seguridad Social, tablas y tipos de cotizacion 2026; AEAT, modelo 130.','Referencias revisadas el 15/09/2026. Enlaces completos en la calculadora.','Tus cifras se procesan y exportan exclusivamente en tu navegador.');download(makePDF(lines),'calcly-resumen-2026.pdf');toast('Resumen PDF generado en tu equipo.');};sync();
